// Slack envía el slash command como form-encoded
const raw = $input.first().json || {};
const body = raw.body || raw;

const text = (body.text || '').trim();
const channel_name = (body.channel_name || '').toLowerCase().trim();
const response_url = body.response_url || '';
const user_name = body.user_name || body.user_id || 'usuario';
const user_id = body.user_id || '';

const CANAL_PERMITIDO = 'oraculo_del_opex';
const is_valid_channel = channel_name === CANAL_PERMITIDO;

if (!is_valid_channel) {
  return [{ json: {
    is_valid: false,
    ack_text: `❌ El comando /opex solo está disponible en el canal #${CANAL_PERMITIDO}.`,
    response_url, text, user_name, user_id, channel_name
  }}];
}

if (!text) {
  return [{ json: {
    is_valid: false,
    ack_text: '❓ Debes escribir una pregunta. Ejemplo: `/opex ¿Cuál es el CAC promedio esta semana?`',
    response_url, text, user_name, user_id, channel_name
  }}];
}

return [{ json: {
  is_valid: true,
  ack_text: `⏳ *Oráculo del OPEX* consultando para @${user_name}...`,
  response_url, text, user_name, user_id, channel_name
}}];
